ki_facts":{"br_coordinate_frame":"Tibia_reference_world_coordinates_not_Oteryn_placement","br_coordinates":[[33394,31919,8]],"br_trade_reference":{"BuyFromPlayer":{},"SellToPlayer":{}},"city":"Cormaya","description":"Zleceniodawczyni The Cradle of Monsters Quest .","location_description":"namiot","npc_lines":["Greetings my friend. It's a relief to see a friendly face in times of trouble.","I was in search of my lost brother. After a long investigation I found most disturbing hints that he amongst others has been abducted for nefarious purposes.","The ruffians that my mercenaries rounded up admitted that they sold their captives to a scientist, that conducts abominable experiments on those captives.","This amoral creature that is known as doctor Marrow has a more than questionable reputation amongst his peers in science.","His disregard of human life and single minded pursuit of his research had him expelled from several institutions despite his scientific genius.","I fear the worst for my dear brother. I beg you to pick up his trail. I've arranged for a passage to the remote island. ...","I plead to you to travel to the island and save my brother from the clutches of doctor Marrow.","A smuggler on Cormaya was the only one, brave enough to set sail to such a remote isle in unknown waters. I will instruct him to ferry you safely to that island. ...","Will you accept this mission? Yes or No?","Thank you so much. I beg you though, please hurry!"],"npc_lines_semantics":"source_utterances_without_trigger_or_state_assignment","profession":"nieznany","quest_references":[{"label":"The Cradle of Monsters Quest","url":"https://tibiopedia.pl/quests/The_Cradle_Of_Monsters_Quest"}],"specialty":null,"tp_coordinate_frame":"tibiopedia-map-pixels-floor-unverified","tp_map_markers":[[3570,2991,7]],"tp_trade_available":"nie","tp_trade_reference":{"BuyFromPlayer":{},"SellToPlayer":{}},"voices_text":null}}
